{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_018PWXv2ioqXAQmopRzP3Pnk","type":"tool_result","content":[{"type":"text","text":"--- a/src/adapters/encounter-diagnosis-adapter.test.ts\n+++ b/src/adapters/encounter-diagnosis-adapter.test.ts\n@@ -203,7 +203,7 @@ describe('EncounterDiagnosisAdapter', () => {\n       formFieldNamespace: 'rfe-forms',\n       uuid: '0e20bb67-5d7f-41e0-96a1-751efc21a96f',\n     });\n-    expect(field.meta.submission.voidedValue).toBe(undefined);\n+    expect(field.meta.submission.voidedValue).toBeNull();\n   });\n \n   it('should void removed diagnosis in edit mode', () => {\n--- a/src/adapters/encounter-diagnosis-adapter.ts\n+++ b/src/adapters/encounter-diagnosis-adapter.ts\n@@ -7,7 +7,7 @@ import {\n   type FormField,\n } from '../types';\n import { type FormContextProps } from '../provider/form-provider';\n-import { gracefullySetSubmission } from '../utils/common-utils';\n+import { clearSubmission, gracefullySetSubmission } from '../utils/common-utils';\n import { isEmpty } from '../validators/form-validator';\n import { isTrue } from '../utils/boolean-utils';\n \n@@ -15,6 +15,7 @@ export let assignedDiagnosesIds: string[] = [];\n \n export const EncounterDiagnosisAdapter: FormFieldValueAdapter = {\n   transformFieldValue: function (field: FormField, value: any, context: FormContextProps) {\n+    clearSubmission(field);\n     if (field.meta.initialValue?.omrsObject && isEmpty(value)) {\n       return gracefullySetSubmission(field, undefined, voidDiagnosis(field.meta.initialValue.omrsObject as OpenmrsObs));\n     }\n--- a/src/adapters/orders-adapter.ts\n+++ b/src/adapters/orders-adapter.ts\n@@ -10,7 +10,8 @@ const defaultCareSetting = '6f0c9a92-6f24-11e3-af88-005056821db0';\n \n export const OrdersAdapter: FormFieldValueAdapter = {\n   transformFieldValue: function (field: FormField, value: any, context: FormContextProps) {\n-    if (context.sessionMode == 'edit' && field.meta.initialValue?.omrsObject) {\n+    clearSubmission(field);\n+    if (context.sessionMode === 'edit' && field.meta.initialValue?.omrsObject) {\n       return editOrder(value, field, context.currentProvider.uuid);\n     }\n     const newValue = constructNewOrder(value, field, context.currentProvider.uuid);\n@@ -70,7 +71,6 @@ function constructNewOrder(value: any, field: FormField, orderer: string) {\n function editOrder(newOrder: any, field: FormField, orderer: string) {\n   const previousOrder = field.meta.initialValue?.omrsObject as OpenmrsResource;\n   if (newOrder === previousOrder?.concept?.uuid) {\n-    clearSubmission(field);\n     return null;\n   }\n   const voided = {\n--- a/src/processors/encounter/encounter-payloads.golden.test.ts\n+++ b/src/processors/encounter/encounter-payloads.golden.test.ts\n@@ -406,6 +406,36 @@ describe('golden encounter payloads: new encounters', () => {\n     await matchGolden(payload, 'new-encounter-orders-and-diagnoses');\n   });\n \n+  it('drops orders and diagnoses that are selected and then cleared', async () => {\n+    const context = await buildScenario({\n+      fields: [\n+        buildField({\n+          id: 'order',\n+          type: 'testOrder',\n+          questionOptions: {\n+            rendering: 'select',\n+            answers: [{ concept: 'malaria-test-concept-uuid', label: 'Malaria smear' }],\n+          },\n+        }),\n+        buildField({\n+          id: 'diagnosis',\n+          type: 'diagnosis',\n+          questionOptions: {\n+            rendering: 'select',\n+            answers: [{ concept: 'malaria-concept-uuid', label: 'Malaria' }],\n+          },\n+        }),\n+      ],\n+    });\n+\n+    applyValues(context, { order: 'malaria-test-concept-uuid', diagnosis: 'malaria-concept-uuid' });\n+    applyValues(context, { order: '', diagnosis: '' });\n+\n+    const payload = toEncounterPayload(context);\n+    expect(payload.orders).toEqual([]);\n+    expect(payload.diagnoses).toEqual([]);\n+  });\n+\n   it('drops hidden and transient fields but